donut=(p,l)=>`<div class="dn"><svg viewBox="0 0 36 36" role="img" aria-label="${l} ${p}%"><circle cx="18" cy="18" r="15.9" fill="none" stroke="var(--b)" stroke-width="3"/><circle cx="18" cy="18" r="15.9" fill="none" stroke="var(--a)" stroke-width="3" stroke-linecap="round" stroke-dasharray="${p} ${100-p}" stroke-dashoffset="25" style="transition:stroke-dasharray .8s"/><text x="18" y="20.6" text-anchor="middle" font-size="7.5" fill="var(--t)">${p}%</text></svg><small class="m">${l}</small></div>`;
function beep(){try{const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);g.gain.value=.05;o.frequency.value=660;o.onended=()=>c.close();o.start();o.stop(c.currentTime+.12)}catch(e){}}
function SK(e){if(!me||e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||$('#modal').className||$('#pal').className)return;if(e.key==='/'){e.preventDefault();A.pal()}else if(e.key==='n'&&can('tasks')){e.preventDefault();A.tnew()}}
function revStats(){const rs=S.reviews,n=rs.length,avg=n?(rs.reduce((a,r)=>a+r.rating,0)/n).toFixed(1):'–',rr=n?Math.round(rs.filter(r=>r.resp==='Responded').length/n*100):0;return`<section class="panel"><div class="ov" style="grid-template-columns:1fr 1fr 2fr"><div><small class="m">Average rating</small><div class="big">${avg}</div></div><div><small class="m">Response rate</small><div class="big">${rr}%</div><small class="m">${rs.filter(r=>r.resp!=='Responded').length} pending</small></div><div>${[5,4,3,2,1].map(k=>bar(k+' ★',rs.filter(r=>r.rating===k).length,n)).join('')}</div></div></section>`}
function cc(){const p=pf(),w=p.w,ot=S.tasks.filter(t=>t.st!=='Completed'&&vis(t)),bugs=ot.filter(t=>t.kind.includes('Bug')).length,pr=S.reviews.filter(r=>r.st==='New').length,ac=S.staff.filter(s=>s.status==='active').length,un=mine().filter(n=>!n.rd.includes(me.id)).length,ov=Math.round(S.prog.reduce((a,x)=>a+x.p,0)/S.prog.length),my=ot.filter(t=>t.to===me.id),soon=my.filter(t=>t.due<now()+3*DAY).length,dq=S.designs.filter(d=>(d.rev===me.id&&['Submitted','Awaiting Approval'].includes(d.st))||(d.by===me.id&&['Draft','In Revision'].includes(d.st))).length,
qa=[['＋','New Task','tasks','tnew'],['★','Review Center','reviews','go:reviews'],['✎','New Announcement','annw','anew'],['◧','Design Studio','design','go:design'],['⊕','Invite Staff','staff','inv'],['⛨','Security','security','go:security'],['↑','Update Progress','progress','prog']].filter(q=>can(q[2])),
mini=(l,v)=>`<div class="pcard static"><small class="m">${l}</small><b class="n">${v}</b></div>`,
hero=`<div class="hero2"><div><small class="m">TRUEAI HEADQUARTERS</small><h1>Welcome back, ${esc(me.name.split(' ')[0])}.</h1><p class="m">Briz AI Operations &amp; Staff Command Center</p></div><div class="acts"><button class="btn" data-a="cust">Customize dashboard</button>${me.role==='owner'?'<button class="btn" data-a="rdl">Reset layout</button>':''}</div></div>`,
qc=w.qa?`<div class="cards qa2">${qa.map(q=>`<button class="pcard qb" data-a="qa" data-k="${q[3]}"><i class="ic">${q[0]}</i>${q[1]}</button>`).join('')}</div>`:'',
ovp=panel('Project overview',`<div class="ov"><div><small class="m">Overall progress</small><div class="big">${ov}%</div><div class="bar"><i style="width:${ov}%"></i></div></div><div><small class="m">Briz AI version</small><b>v0.4.0</b><small class="m">Development stage</small><b>Alpha</b></div><div><small class="m">Current milestone</small><b>Android app beta</b><small class="m">Next milestone</small><b>WhatsApp pilot</b></div><div><small class="m">Last update</small><b>${fd(Math.max(...S.prog.map(x=>x.u)))}</b><small class="m">Status</small><b>In development</b></div></div><div class="cards mini">${mini('Active staff',ac)}${mini('Open tasks',ot.length)}${mini('Open bugs',bugs)}${mini('Pending reviews',pr)}</div>`,bdg('DEMO DATA')),
prog=w.prog?panel('Briz AI project progress',`<div class="cards">${S.prog.map((x,i)=>`<button class="pcard" data-a="pa" data-n="${i}"><div class="row"><b>${esc(x.n)}</b><span class="m">${x.p}%</span></div><div class="bar"><i style="width:${x.p}%"></i></div><small class="m">${pst(x.p)} · updated ${fd(x.u)}</small></button>`).join('')}</div>`,can('progress')?'<button class="btn sm" data-a="prog">Update progress</button>':''):'',
mw=w.my?panel('My work',`<div class="cards"><button class="pcard" data-a="go" data-r="tasks"><small class="m">Open tasks</small><b class="n">${my.length}</b><small class="m">${soon} due within 3 days</small></button>${can('reviews')?`<button class="pcard" data-a="go" data-r="reviews"><small class="m">Pending reviews</small><b class="n">${pr}</b></button>`:''}${can('design')?`<button class="pcard" data-a="go" data-r="design"><small class="m">Design requests</small><b class="n">${dq}</b></button>`:''}<button class="pcard" data-a="go" data-r="notifs"><small class="m">Unread notifications</small><b class="n">${un}</b></button></div>${my.slice(0,4).map(t=>`<div class="ev sp" data-a="tv" data-id="${t.id}" style="cursor:pointer"><div><b>${esc(t.title)}</b><br><small class="m">${t.st} · due ${fd(t.due)}</small></div>${bdg(t.pri,pc(t.pri))}</div>`).join('')}`):'',
act=!w.act?'':can('activity')?panel('Recent activity',evs(S.act.slice(0,6)),'<button class="btn sm" data-a="go" data-r="activity">View all</button>'):panel('Design activity',S.designs.map(d=>`<div class="ev sp"><div><b>${esc(d.name)}</b><br><small class="m">v${d.v} · due ${fd(d.due)}</small></div>${bdg(d.st)}</div>`).join('')||'<p class="empty">No designs yet.</p>'),
an=!w.ann?'':panel('Announcements',S.ann.filter(a=>!a.exp||a.exp>now()).slice(0,3).map(a=>`<div class="ev sp"><div><b>${esc(a.title)}</b><br><small class="m">${esc(a.body.slice(0,90))}</small></div>${bdg(a.pri,a.pri==='High'?'e':'')}</div>`).join('')||'<p class="empty">No announcements yet.</p>','<button class="btn sm" data-a="go" data-r="ann">Open</button>');
return hero+qc+ovp+(p.first==='my'?mw+prog:prog+mw)+`<div class="g2">${act}${an}</div>`}
A.pa=d=>{const x=S.prog[+d.n],ws=x.n.split(/[ \/]/).filter(w=>w.length>2).map(w=>w.toLowerCase()),rel=S.tasks.filter(t=>vis(t)&&ws.some(w=>(t.title+t.desc+t.kind).toLowerCase().includes(w)));modal(x.n,`<div class="big">${x.p}%</div><div class="bar"><i style="width:${x.p}%"></i></div><div class="kv"><span>Status</span><b>${pst(x.p)}</b><span>Last updated</span><b>${fd(x.u)}</b><span>Responsible</span><b>${esc(nm(RESP[x.n]))}</b></div><h3>Related tasks</h3>${rel.map(t=>`<div class="ev sp"><span>${esc(t.title)}</span>${bdg(t.st)}</div>`).join('')||'<p class="m">No related tasks.</p>'}<h3>Related bugs</h3>${rel.filter(t=>t.kind.includes('Bug')).map(t=>`<div class="ev sp"><span>${esc(t.title)}</span>${bdg(t.pri,pc(t.pri))}</div>`).join('')||'<p class="m">No related bugs.</p>'}<h3>Recent activity</h3>${evs(S.act.filter(a=>a.it.includes(x.n)).slice(0,4))}`,null,'',1)};
A.cust=()=>{const p=pf(),T=(k,l)=>`<label class="ck"><input type="checkbox" name="${k}"${p.w[k]?' checked':''}> ${l}</label>`;modal('Customize dashboard',`${T('prog','Project progress')}${T('my','My work')}${T('act','Recent activity')}${T('ann','Announcements')}${T('qa','Quick actions')}<label>Show first</label><select name="first">${opts([['prog','Project progress'],['my','My work']],p.first)}</select><label>Density</label><select name="dens">${opts([['comfortable','Comfortable'],['compact','Compact'],['spacious','Spacious']],p.dens)}</select><label>Animations</label><select name="anim">${opts([['full','Full'],['reduced','Reduced'],['off','Off']],p.anim)}</select>`,f=>{['prog','my','act','ann','qa'].forEach(k=>p.w[k]=f[k]?1:0);Object.assign(p,{first:f.first,dens:f.dens,anim:f.anim});applyTheme();mx();fin('Dashboard updated')},'Save',1)};
A.rdp=()=>ask('Reset your dashboard preferences to defaults?',()=>{Object.assign(pf(),{w:{prog:1,my:1,act:1,ann:1,qa:1},first:'prog',land:'cc'});fin('Dashboard preferences reset')});A.rdl=()=>guard('staff')&&A.rdp();
A.qa=d=>{const[k,r]=d.k.split(':');k==='go'?go(r):A[k]()};
A.prog=()=>{if(!guard('progress'))return;modal('Update Briz AI progress',`<div class="g3">${S.prog.map((p,i)=>`<div><label>${esc(p.n)} (%)</label><input type="number" min="0" max="100" name="p${i}" value="${p.p}"></div>`).join('')}</div>`,f=>{if(!guard('progress'))return;let c=0;S.prog.forEach((p,i)=>{const v=Math.max(0,Math.min(100,Math.round(+f['p'+i])));if(!isNaN(v)&&v!==p.p){p.p=v;p.u=now();c++;log('Progress updated',`${p.n} → ${v}%`)}});if(c)notify('all','Progress','Briz AI project progress was updated','cc');mx();save();render();toast(c?'Progress updated':'No changes to save')})};
/* ---------- TASKS ---------- */
function tasks(){const p=pf(),q=V.q.toLowerCase(),PR={High:0,Medium:1,Low:2};let l=S.tasks.filter(t=>vis(t)&&(!q||(t.title+t.desc+nm(t.to)).toLowerCase().includes(q))&&(!V.f||t.st===V.f)&&(!V.pf||t.pri===V.pf));
l.sort(V.so==='pri'?(a,b)=>PR[a.pri]-PR[b.pri]:V.so==='new'?(a,b)=>b.at-a.at:(a,b)=>a.due-b.due);
const body=p.tv==='board'?`<div class="kb">${ST.map(s=>`<div class="col" data-drop="${s}"><h3>${s} <small class="m">${l.filter(t=>t.st===s).length}</small></h3>${l.filter(t=>t.st===s).map(t=>`<div class="kc" draggable="true" data-drag="${t.id}" data-a="tv" data-id="${t.id}"><b>${esc(t.title)}</b><p class="m">${esc(nm(t.to))} · ${fd(t.due)}</p>${bdg(t.pri,pc(t.pri))}<select data-c="ts" data-id="${t.id}" aria-label="Status">${opts(ST,t.st)}</select></div>`).join('')}</div>`).join('')}</div>`:tbl(['Task','Assignee','Priority','Status','Deadline',''],l.map(t=>`<tr class="hv"><td><button class="lk" data-a="tv" data-id="${t.id}">${esc(t.title)}</button><br><small class="m">${t.kind}</small></td><td><span class="av sm">${ini(nm(t.to))}</span>${esc(nm(t.to))}</td><td>${bdg(t.pri,pc(t.pri))}</td><td><select data-c="ts" data-id="${t.id}" aria-label="Status">${opts(ST,t.st)}</select></td><td>${dl(t)}</td><td><button class="btn sm dng" data-a="td" data-id="${t.id}">Delete</button></td></tr>`),'No tasks found.');
return panel('Tasks',srch('Search tasks',`<select data-i="f" aria-label="Status filter">${opts([['','All statuses'],...ST],V.f)}</select><select data-i="pf" aria-label="Priority filter">${opts([['','All priorities'],'High','Medium','Low'],V.pf)}</select><select data-i="so" aria-label="Sort">${opts([['','Sort: deadline'],['pri','Sort: priority'],['new','Sort: newest']],V.so)}</select><div class="seg"><button class="btn sm${p.tv!=='board'?' on':''}" data-a="tvw" data-v="list">List</button><button class="btn sm${p.tv==='board'?' on':''}" data-a="tvw" data-v="board">Board</button></div>`)+body,'<button class="btn pri" data-a="tnew">New task</button>')}
function taskM(t){const n=!t;t=t||{title:'',desc:'',to:me.id,pri:'Medium',st:'Not Started',due:now()+7*DAY,kind:'Task'};
const ex=n?'':`<div class="acts" style="margin-top:14px"><button type="button" class="btn sm" data-a="tdup" data-id="${t.id}">Duplicate</button><button type="button" class="btn sm" data-a="tarc" data-id="${t.id}">Archive</button></div><h3>Comments</h3>${t.cm.map(c=>`<p class="cm"><b>${esc(nm(c.u))}</b> · ${ft(c.at)}<br>${esc(c.x)}</p>`).join('')||'<p class="m">No comments yet.</p>'}<div class="row"><input id="cin" data-id="${t.id}" placeholder="Add a comment" aria-label="Add a comment"><button type="button" class="btn" data-a="cmt" data-id="${t.id}">Post</button></div><h3>History</h3>${t.h.slice().reverse().map(h=>`<p class="m">${ft(h[0])} · ${esc(h[1])}</p>`).join('')}`;
modal(n?'New task':'Task',`<label>Title</label><input name="title" required value="${esc(t.title)}"><label>Description</label><textarea name="desc" rows="3">${esc(t.desc)}</textarea><div class="g3"><div><label>Assignee</label><select name="to">${so(t.to)}</select></div><div><label>Priority</label><select name="pri">${opts(['Low','Medium','High'],t.pri)}</select></div><div><label>Status</label><select name="st">${opts(ST,t.st)}</select></div><div><label>Deadline</label><input type="date" name="due" value="${new Date(t.due).toISOString().slice(0,10)}"></div><div><label>Type</label><select name="kind">${opts(KD,t.kind)}</select></div></div>${ex}`,f=>{if(!guard('tasks'))return;
const x={title:f.title.trim(),desc:f.desc.trim(),to:f.to,pri:f.pri,st:f.st,kind:f.kind,due:new Date(f.due+'T12:00').getTime()||t.due};
if(n){Object.assign(t,x,{id:rid('t'),at:now(),cm:[],h:[[now(),'Created by '+me.name]]});S.tasks.unshift(t);log('Task created',x.title);x.to&&notify([x.to],'Task assignment',`New task assigned: ${x.title}`,'tasks')}
else{if(x.to!==t.to){t.h.push([now(),'Assigned to '+nm(x.to)]);log('Task assigned',x.title);x.to&&notify([x.to],'Task assignment',`New task assigned: ${x.title}`,'tasks')}if(x.pri!==t.pri)t.h.push([now(),'Priority → '+x.pri]);if(x.st!==t.st){t.h.push([now(),'Status → '+x.st]);x.st==='Completed'&&log('Task completed',x.title)}Object.assign(t,x);log('Task updated',x.title)}
mx();save();render();toast(n?'Task created successfully':'Task updated')},n?'Create task':'Save changes',1)}
A.tdup=d=>{const t=S.tasks.find(x=>x.id===d.id);if(!t||!vis(t)||!guard('tasks'))return;S.tasks.unshift({...t,id:rid('t'),title:t.title+' (copy)',st:'Not Started',at:now(),cm:[],h:[[now(),'Duplicated by '+me.name]]});log('Task duplicated',t.title);mx();fin('Task duplicated')};
A.tarc=d=>{const t=S.tasks.find(x=>x.id===d.id);if(!t||!vis(t)||!guard('tasks'))return;t.arch=1;log('Task archived',t.title);mx();fin('Task archived')};
function setSt(id,st){const t=S.tasks.find(x=>x.id===id);if(!t||!vis(t)||!guard('tasks')||t.st===st)return;t.st=st;t.h.push([now(),`Status → ${st} by ${me.name}`]);log(st==='Completed'?'Task completed':'Task status changed',t.title);t.to&&t.to!==me.id&&notify([t.to],'Task update',`"${t.title}" moved to ${st}`,'tasks');fin(`Task moved to ${st}`)}
C.ts=t=>setSt(t.dataset.id,t.value);A.tnew=()=>guard('tasks')&&taskM();A.tv=d=>{const t=S.tasks.find(x=>x.id===d.id);t&&vis(t)&&taskM(t)};A.tvw=d=>{pf().tv=d.v;save();render()};
A.td=d=>{const t=S.tasks.find(x=>x.id===d.id);if(!t||!vis(t)||!guard('tasks'))return;ask(`Delete “${esc(t.title)}”? This cannot be undone.`,()=>{S.tasks=S.tasks.filter(x=>x!==t);log('Task deleted',t.title);fin('Task deleted')})};
A.cmt=d=>{const t=S.tasks.find(x=>x.id===d.id),i=$('#cin'),x=i&&i.value.trim();if(!t||!x||!vis(t)||!guard('tasks'))return;t.cm.push({u:me.id,at:now(),x});t.h.push([now(),me.name+' commented']);log('Task comment added',t.title);t.to&&t.to!==me.id&&notify([t.to],'Task update',`New comment on "${t.title}"`,'tasks');save();taskM(t);render()};
/* ---------- REVIEWS ---------- */
function reviews(){const q=V.q.toLowerCase(),l=S.reviews.filter(r=>(!q||(r.text+r.src+r.cat+nm(r.to)).toLowerCase().includes(q))&&(!V.f||r.st===V.f));l.sort(V.so==='rating'?(a,b)=>a.rating-b.rating:(a,b)=>b.at-a.at);
return revStats()+panel('Review Center',srch('Search reviews',`<select data-i="f" aria-label="Status filter">${opts([['','All statuses'],'New','In Progress','Resolved'],V.f)}</select><select data-i="so" aria-label="Sort">${opts([['','Sort: newest'],['rating','Sort: lowest rating']],V.so)}</select>`)+tbl(['Rating','Review','Source','Date','Category','Status','Assigned','Response'],l.map(r=>`<tr class="hv" data-a="rv" data-id="${r.id}"><td class="star">${'★'.repeat(r.rating)}</td><td>${esc(r.text)}</td><td>${r.src}</td><td>${fd(r.at)}</td><td>${r.cat}</td><td>${bdg(r.st,r.st==='New'?'w':r.st==='Resolved'?'ok':'')}</td><td>${esc(nm(r.to))}</td><td>${r.resp}</td></tr>`),'No reviews found.'))}
function revM(id){const r=S.reviews.find(x=>x.id===id);if(!r||!guard('reviews'))return;modal('Review details',`<p class="star">${'★'.repeat(r.rating)}</p><p>${esc(r.text)}</p><p class="m">${r.src} · ${fd(r.at)} · ${r.cat}</p><div class="g3"><div><label>Assigned staff</label><select name="to">${so(r.to)}</select></div><div><label>Status</label><select name="st">${opts(['New','In Progress','Resolved'],r.st)}</select></div><div><label>Response</label><select name="resp">${opts(['Not Responded','Responded'],r.resp)}</select></div></div><h3>Internal notes</h3>${r.notes.map(n=>`<p class="cm"><b>${esc(nm(n.u))}</b> · ${ft(n.at)}<br>${esc(n.x)}</p>`).join('')}<label>Add note</label><textarea name="note" rows="2"></textarea>`,f=>{if(!guard('reviews'))return;if(f.to&&f.to!==r.to)notify([f.to],'New review',`Review assigned to you: "${r.text.slice(0,40)}"`,'reviews');Object.assign(r,{to:f.to,st:f.st,resp:f.resp});f.note.trim()&&r.notes.push({u:me.id,at:now(),x:f.note.trim()});log('Review updated',r.cat+' review');mx();save();render();toast('Review updated')},'Save changes',1)}
A.rv=d=>revM(d.id);
/* ---------- DESIGN STUDIO ---------- */
function design(){return panel('Design Studio',tbl(['Design','Designer','Reviewer','Deadline','Version','Status',''],S.designs.map(d=>`<tr><td>${esc(d.name)}</td><td>${esc(nm(d.by))}</td><td>${esc(nm(d.rev))}</td><td>${fd(d.due)}</td><td>v${d.v}</td><td>${bdg(d.st,d.st==='Approved'?'ok':d.st==='In Revision'?'w':'')}</td><td class="acts">${['Draft','In Revision'].includes(d.st)?`<button class="btn sm pri" data-a="ds" data-k="sub" data-id="${d.id}">Submit</button>`:''}${can('dreview')&&['Submitted','Awaiting Approval'].includes(d.st)?`<button class="btn sm" data-a="ds" data-k="rev" data-id="${d.id}">Request revision</button><button class="btn sm pri" data-a="ds" data-k="ok" data-id="${d.id}">Approve</button>`:''}<button class="btn sm" data-a="dfb" data-id="${d.id}">Feedback (${d.fb.length})</button></td></tr>`),'No designs yet.'),'<button class="btn pri" data-a="dnew">New design</button>')}
A.ds=d=>{const x=S.designs.find(z=>z.id===d.id);if(!x||!guard(d.k==='sub'?'design':'dreview'))return;
if(d.k==='sub'){x.st=x.st==='Draft'?'Submitted':'Awaiting Approval';log('Design submitted',x.name);notify([x.rev],'Design feedback',`"${x.name}" was submitted for review`,'design');fin('Design submitted')}
else if(d.k==='ok'){x.st='Approved';log('Design approved',x.name);notify([x.by],'Design feedback',`"${x.name}" was approved`,'design');fin('Design approved')}
else{x.st='In Revision';x.v++;log('Revision requested',x.name);notify([x.by],'Design feedback',`Revision requested for "${x.name}"`,'design');fin('Revision requested')}};
A.dfb=d=>{const x=S.designs.find(z=>z.id===d.id);if(!x||!guard('design'))return;modal(x.name,`${x.fb.map(n=>`<p class="cm"><b>${esc(nm(n.u))}</b> · ${ft(n.at)}<br>${esc(n.x)}</p>`).join('')||'<p class="m">No feedback yet.</p>'}<label>Add feedback</label><textarea name="x" rows="3" required></textarea>`,f=>{if(!guard('design'))return;x.fb.push({u:me.id,at:now(),x:f.x.trim()});log('Design feedback added',x.name);notify([me.id===x.by?x.rev:x.by],'Design feedback',`New feedback on "${x.name}"`,'design');mx();fin('Feedback added')},'Add feedback')};
A.dnew=()=>guard('design')&&modal('New design',`<label>Name</label><input name="name" required><label>Reviewer</label><select name="rev">${opts(S.staff.filter(s=>s.role==='owner').map(s=>[s.id,s.name]))}</select><label>Deadline</label><input type="date" name="due" required>`,f=>{if(!guard('design'))return;S.designs.unshift({id:rid('d'),name:f.name.trim(),by:me.id,rev:f.rev,due:new Date(f.due+'T12:00').getTime(),st:'Draft',v:1,fb:[]});log('Design created',f.name.trim());mx();fin('Design created')},'Create design');
