const RG=[['7','7 days'],['30','30 days'],['90','90 days'],['180','6 months'],['all','All time']],AF={All:0,Security:a=>a.sec,Tasks:a=>/task/i.test(a.a),Reviews:a=>/review/i.test(a.a),Designs:a=>/design|revision/i.test(a.a),Staff:a=>/staff|invit|account|session/i.test(a.a),Announcements:a=>/announcement/i.test(a.a)};
